/** 9. Nothing — Official dot-matrix signature logomark */
export function NothingLogo({ color = '#000000', size = 26 }: BrandLogoProps) {
  // 5x5 dot-matrix signature "N" glyph characteristic of Nothing OS
  const dotR = 1.6;
  // Dots that form the Nothing "N"
  const dots = [
    // Column 1
    { cx: 4, cy: 4 },
    { cx: 4, cy: 9 },
    { cx: 4, cy: 14 },
    { cx: 4, cy: 19 },
    { cx: 4, cy: 24 },
    // Diagonal
    { cx: 9, cy: 9 },
    { cx: 14, cy: 14 },
    { cx: 19, cy: 19 },
    // Column 2
    { cx: 24, cy: 4 },
    { cx: 24, cy: 9 },
    { cx: 24, cy: 14 },
    { cx: 24, cy: 19 },
    { cx: 24, cy: 24 },
  ];

  return (
    <Svg width={size} height={size} viewBox="0 0 28 28">
      {dots.map((d, i) => (
        <Circle key={i} cx={d.cx} cy={d.cy} r={dotR} fill={color} />
      ))}
    </Svg>
  );
}

