/** 12. Other — Clean solid 3-dot ellipsis */
export function OtherBrandLogo({ color = '#000000', size = 26 }: BrandLogoProps) {
  const dotR = 2.4;
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24">
      <Circle cx="6" cy="12" r={dotR} fill={color} />
      <Circle cx="12" cy="12" r={dotR} fill={color} />
      <Circle cx="18" cy="12" r={dotR} fill={color} />
    </Svg>
  );
}

/** Map brand names to corresponding logo components */
export const BRAND_LOGO_MAP: Record<
  string,
  React.ComponentType<{ color: string; size: number }>
> = {
  Samsung: SamsungLogo,
  Apple: AppleLogo,
  Xiaomi: XiaomiLogo,
  Vivo: VivoLogo,
  Oppo: OppoLogo,
  Realme: RealmeLogo,
  OnePlus: OnePlusLogo,
  Motorola: MotorolaLogo,
  Nothing: NothingLogo,
  Google: GoogleLogo,
  Poco: PocoLogo,
  other: OtherBrandLogo,
  Other: OtherBrandLogo,
};

/** Helper to get the logo component for any brand name */
export function getBrandLogo(brandName?: string | null) {
  if (!brandName) return OtherBrandLogo;
  const match = Object.keys(BRAND_LOGO_MAP).find(
    k => k.toLowerCase() === brandName.toLowerCase()
  );
  return match ? BRAND_LOGO_MAP[match] : OtherBrandLogo;
}
